#include "protocol.hpp"
namespace mobile_robot::protocol {
uint16_t crc16_ccitt_false(const uint8_t* data,const size_t size){uint16_t crc=0xFFFFU;for(size_t i=0;i<size;++i){crc^=static_cast<uint16_t>(data[i])<<8U;for(uint8_t bit=0;bit<8U;++bit){crc=(crc&0x8000U)!=0U?static_cast<uint16_t>((crc<<1U)^0x1021U):static_cast<uint16_t>(crc<<1U);}}return crc;}
void Parser::reset(){state_=State::kHeader;packet_=Packet{};index_=0;crc_bytes_[0]=0;crc_bytes_[1]=0;}
bool Parser::push(const uint8_t byte,Packet& packet){switch(state_){case State::kHeader:reinterpret_cast<uint8_t*>(&packet_.header)[index_++]=byte;if(index_==sizeof(Header)){if(packet_.header.magic!=config::kProtocolMagic||packet_.header.version!=config::kProtocolVersion||packet_.header.payload_size>config::kMaximumPayloadSize){reset();return false;}index_=0;state_=packet_.header.payload_size==0U?State::kCrc:State::kPayload;}break;case State::kPayload:packet_.payload[index_++]=byte;if(index_==packet_.header.payload_size){index_=0;state_=State::kCrc;}break;case State::kCrc:crc_bytes_[index_++]=byte;if(index_==sizeof(uint16_t)){uint16_t received_crc=0;std::memcpy(&received_crc,crc_bytes_,sizeof(received_crc));uint8_t buffer[sizeof(Header)+config::kMaximumPayloadSize]{};std::memcpy(buffer,&packet_.header,sizeof(Header));std::memcpy(buffer+sizeof(Header),packet_.payload,packet_.header.payload_size);const uint16_t calculated_crc=crc16_ccitt_false(buffer,sizeof(Header)+packet_.header.payload_size);if(received_crc==calculated_crc){packet_.crc=received_crc;packet=packet_;reset();return true;}reset();}break;}return false;}
}
